rss.channel:
{% if page.target == "blog" -%}
  {{ site.base_url }}blog/
  Blake Rain's Blog Posts
  Recent blog posts by Blake Rain

{%- else -%}
  {{ site.base_url }}
  Blake Rain
  Recent content by Blake Rain

{%- endif %}
en-GB
blake@blakerain.com (Blake Rain)
blake@blakerain.com (Blake Rain)
{{ env.now | datetime(format="rfc2822") }}
{% if page.target == "blog" -%}
  {% set pages = load_pages("blog", target="rss") -%}
{%- else -%}
  {% set pages = load_pages("blog", target="rss") -%}
  {% set pages = pages | chain(load_pages("weeknotes", target="rss")) -%}
{%- endif %}
{%- set pages = pages | sort(attribute="frontmatter.date") | reverse -%}
{%- set pages = pages
  | rejectattr("base", "eq", "blog")
  | rejectattr("base", "eq", "weeknotes") -%}
{% for page in pages -%}
{% if not page.frontmatter.rss or not page.frontmatter.rss.skip -%}


  {%- set item_title = page.frontmatter.title -%}
  {%- if not item_title and page.base is startingwith "weeknotes/" -%}
    {%- set item_title = "Weeknote " ~ (page.base | split("/") | last) -%}
  {%- endif %}
  {{ item_title | default(page.path) }}
  {{ base_url(path_parent(page.path)) | safe }}/
  {%- if page.frontmatter.date -%}
    {{ page.frontmatter.date | datetime(format="rfc2822") }}
  {%- else -%}
    {{ page.metadata.modified | datetime(format="rfc2822") }}
  {%- endif %}
  blake@blakerain.com (Blake Rain)
  {{ base_url(path_parent(page.path)) | safe }}

    {{ page.content | safe }}
    <hr>
    <p>Thanks for reading this post via RSS! 👋</p>
    <a href="mailto:blake@blakerain.com?subject=Feedback on {{ page.path }}">Reply to this post by email</a>


{%- endif %}
{% endfor %}
